import type { ICtx, ScheduleHandle } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { type Group, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createEnemyVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const MOVE_SPEED = 2.5;
const DETECTION_RADIUS = 8;
const CHASE_STOP_DISTANCE = 4;
const FIRE_INTERVAL = 1.2;
const PATROL_WAIT_TIME = 2;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  health: number;
  alive = true;
  #state: "patrol" | "chase" = "patrol";
  #currentWaypoint = 0;
  #waypoints: Vector3[];
  #patrolDirection = 1;
  #lastChaseDirection = new Vector3(0, 0, -1);
  #detectionShape = CollisionShape3D.sphere(DETECTION_RADIUS);
  #fireTimer = 0;
  #patrolTimer = 0;
  #scanHandle: ScheduleHandle | undefined;
  #onFire: (origin: Vector3, direction: Vector3) => void;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    waypoints: Vector3[],
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3, direction: Vector3) => void;
    } = {},
  ) {
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#waypoints = waypoints.length > 0 ? waypoints : [position.clone()];
    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);
    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.35),
    });
  }

  startScanning(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const hits = directSpaceState(ctx.physics).intersectShape({
        collisionMask: PLAYER_LAYER,
        maxResults: 1,
        position: this.mesh.position,
        shape: this.#detectionShape,
      });
      const playerDetected = hits.some((hit) => hit.body.id === playerBodyId);
      if (playerDetected && this.#state === "patrol") {
        this.#state = "chase";
      } else if (!playerDetected && this.#state === "chase") {
        this.#state = "patrol";
        this.#patrolTimer = PATROL_WAIT_TIME;
      }
      this.#scanHandle = ctx.after(0.2, scan);
    };
    this.#scanHandle = ctx.after(0.2, scan);
  }

  update(ctx: GameCtx, dt: number, playerPosition: Vector3): void {
    if (!this.alive) return;

    if (this.#state === "patrol") {
      this.#updatePatrol(dt);
    } else {
      this.#updateChase(dt, playerPosition);
    }

    this.body.moveAndSlide(dt);
    this.#updateFiring(dt, playerPosition);
  }

  #updatePatrol(dt: number): void {
    this.#patrolTimer -= dt;
    if (this.#patrolTimer > 0) {
      this.body.velocity.set(0, 0, 0);
      return;
    }

    const target = this.#waypoints[this.#currentWaypoint];
    if (!target) return;

    const direction = target.clone().sub(this.mesh.position);
    const distance = direction.length();

    if (distance < 0.5) {
      this.#currentWaypoint += this.#patrolDirection;
      if (this.#currentWaypoint >= this.#waypoints.length) {
        this.#currentWaypoint = this.#waypoints.length - 2;
        this.#patrolDirection = -1;
      } else if (this.#currentWaypoint < 0) {
        this.#currentWaypoint = 1;
        this.#patrolDirection = 1;
      }
      this.#patrolTimer = PATROL_WAIT_TIME;
      this.body.velocity.set(0, 0, 0);
    } else {
      direction.normalize();
      this.body.velocity.x = direction.x * MOVE_SPEED;
      this.body.velocity.z = direction.z * MOVE_SPEED;
      this.#lastChaseDirection.copy(direction);
    }
  }

  #updateChase(dt: number, playerPosition: Vector3): void {
    const direction = playerPosition.clone().sub(this.mesh.position);
    const distance = direction.length();

    if (distance < CHASE_STOP_DISTANCE) {
      this.body.velocity.set(0, 0, 0);
    } else {
      direction.normalize();
      this.body.velocity.x = direction.x * MOVE_SPEED * 1.4;
      this.body.velocity.z = direction.z * MOVE_SPEED * 1.4;
      this.#lastChaseDirection.copy(direction);
    }
  }

  #updateFiring(dt: number, playerPosition: Vector3): void {
    if (this.#state !== "chase") {
      this.#fireTimer = 0;
      return;
    }

    this.#fireTimer -= dt;
    if (this.#fireTimer > 0) return;

    const fireOrigin = this.mesh.position.clone().add(new Vector3(0.3, 0.8, 0));
    const direction = playerPosition.clone().sub(fireOrigin).normalize();
    this.#onFire(fireOrigin, direction);
    this.#fireTimer = FIRE_INTERVAL;
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    this.body.velocity.set(0, 0, 0);
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      health: this.health,
      position: this.mesh.position.toArray(),
      state: this.#state,
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

